/* 학습 해설
 * Atomic64 조건 감소·시도한 결과와 실제 저장 구분
 * 원문 generic 64비트 원자 연산을 읽어 주소 해시 잠금, 보호된 읽기·교체·조건 갱신과 매크로 생성 기술의 원리를 배웁니다.
 * dec_if_positive는 잠금 아래 counter-1을 val에 계산하고 val이 0 이상일 때만 저장합니다. 반환은 항상 계산한 val입니다. 원래 1이면 0을 저장하고 0을 반환하며, 원래 0이면 저장은 그대로 0이고 반환은 -1입니다. 따라서 반환을 현재 저장 값과 언제나 같다고 해석하면 실패 경로를 놓칩니다. 이것은 포화·수명 보호를 갖춘 refcount API와 동일한 의미가 아닙니다.
 * 정상적인 비음수 자원 counter에서 감소 성공 조건과 실패 시 값 유지 여부를 확인합니다. 반환이 음수인지 검사할 때 저장 값도 별도로 추적하세요. 참조 수명에는 전용 refcount 계약을 검토하고 이 산술 함수 이름만으로 수명 보호를 가정하지 않습니다.
 */
s64 generic_atomic64_dec_if_positive(atomic64_t *v)
{
	unsigned long flags;
	raw_spinlock_t *lock = lock_addr(v);
	s64 val;

	raw_spin_lock_irqsave(lock, flags);
	val = v->counter - 1;
	if (val >= 0)
		v->counter = val;
	raw_spin_unlock_irqrestore(lock, flags);
	return val;
}
EXPORT_SYMBOL(generic_atomic64_dec_if_positive);

s64 generic_atomic64_cmpxchg(atomic64_t *v, s64 o, s64 n)
{
	unsigned long flags;
	raw_spinlock_t *lock = lock_addr(v);
	s64 val;

	raw_spin_lock_irqsave(lock, flags);
	val = v->counter;
	if (val == o)
		v->counter = n;
	raw_spin_unlock_irqrestore(lock, flags);

/* 학습 해설
 * Atomic64 compare exchange·성공 표시 대신 이전 값 반환
 * 원문 generic 64비트 원자 연산을 읽어 주소 해시 잠금, 보호된 읽기·교체·조건 갱신과 매크로 생성 기술의 원리를 배웁니다.
 * cmpxchg는 잠금 아래 이전 counter를 val에 읽고 val==o일 때만 n을 저장한 뒤 val을 반환합니다. 반환 자체는 bool이 아니며 성공 여부는 반환 값이 기대값 o와 같은지 비교하여 판단합니다. 실패하면 counter는 유지되고 관찰한 이전 값이 반환됩니다. 이 backend는 명령 기반 CAS 대신 잠금으로 같은 비교·조건 교환을 수행합니다.
 * counter 5에서 expected 4, new 9이면 반환 5와 저장 5를 기록하세요. 재시도 알고리즘에서는 관찰한 값을 기반으로 새 후보를 계산할 수 있습니다. 교환의 원자성과 객체의 수명 확보, ABA 같은 상위 프로토콜 문제를 별도로 검토합니다.
 */
s64 generic_atomic64_cmpxchg(atomic64_t *v, s64 o, s64 n)
{
	unsigned long flags;
	raw_spinlock_t *lock = lock_addr(v);
	s64 val;

	raw_spin_lock_irqsave(lock, flags);
	val = v->counter;
	if (val == o)
		v->counter = n;
	raw_spin_unlock_irqrestore(lock, flags);
	return val;
}
EXPORT_SYMBOL(generic_atomic64_cmpxchg);

s64 generic_atomic64_xchg(atomic64_t *v, s64 new)
{
	unsigned long flags;
	raw_spinlock_t *lock = lock_addr(v);
	s64 val;

	raw_spin_lock_irqsave(lock, flags);
	val = v->counter;
	v->counter = new;
	raw_spin_unlock_irqrestore(lock, flags);
	return val;

/* 학습 해설
 * Atomic64 exchange·무조건 교체와 이전 값 확보
 * 원문 generic 64비트 원자 연산을 읽어 주소 해시 잠금, 보호된 읽기·교체·조건 갱신과 매크로 생성 기술의 원리를 배웁니다.
 * xchg는 잠금 안에서 counter를 val에 복사하고 new를 무조건 저장한 뒤 이전 val을 반환합니다. cmpxchg와 달리 기대값 비교 분기가 없습니다. 이 호출을 통해 이전 값 확보와 새 값 교체가 하나의 보호된 연산이 됩니다. counter를 직접 읽은 뒤 따로 set하는 조합은 두 호출 사이 갱신을 허용하므로 같은 원자적 교체가 아닙니다.
 * 이전 상태를 회수하며 새 상태를 기록해야 할 때 조건 교환과 무조건 교환 중 맞는 API를 고릅니다. 결과를 새 값으로 착각하지 않도록 반환과 저장을 두 칸으로 추적합니다. 실제 payload 보호와 수명은 별도 동기화 계약을 확인합니다.
 */
s64 generic_atomic64_xchg(atomic64_t *v, s64 new)
{
	unsigned long flags;
	raw_spinlock_t *lock = lock_addr(v);
	s64 val;

	raw_spin_lock_irqsave(lock, flags);
	val = v->counter;
	v->counter = new;
	raw_spin_unlock_irqrestore(lock, flags);
	return val;
}
EXPORT_SYMBOL(generic_atomic64_xchg);

s64 generic_atomic64_fetch_add_unless(atomic64_t *v, s64 a, s64 u)
{
	unsigned long flags;
	raw_spinlock_t *lock = lock_addr(v);
	s64 val;

	raw_spin_lock_irqsave(lock, flags);
	val = v->counter;
	if (val != u)
		v->counter += a;
	raw_spin_unlock_irqrestore(lock, flags);

/* 학습 해설
 * Atomic64 add unless·금지 값 검사와 이전 값 반환
 * 원문 generic 64비트 원자 연산을 읽어 주소 해시 잠금, 보호된 읽기·교체·조건 갱신과 매크로 생성 기술의 원리를 배웁니다.
 * fetch_add_unless는 이전 counter를 val에 복사하고 val!=u일 때만 a를 더합니다. 반환은 갱신 여부와 관계없이 이전 val입니다. 이전 값이 금지 값 u와 같은지를 비교하여 실제 덧셈 여부를 판단할 수 있습니다. 금지 값 하나를 검사하는 조건이지 모든 음수·overflow·객체 수명을 방어하는 일반 검증 함수는 아닙니다.
 * counter 0에서 u=0이면 더하지 않는 경로와 counter 5에서 u=0이면 더하는 경로를 비교하세요. 반환을 bool처럼 쓰지 말고 u와의 일치 여부를 읽습니다. 금지 값과 증가량의 도메인을 정의하고 wrap으로 금지 값에 도달할 가능성도 검토합니다.
 */
s64 generic_atomic64_fetch_add_unless(atomic64_t *v, s64 a, s64 u)
{
	unsigned long flags;
	raw_spinlock_t *lock = lock_addr(v);
	s64 val;

	raw_spin_lock_irqsave(lock, flags);
	val = v->counter;
	if (val != u)
		v->counter += a;
	raw_spin_unlock_irqrestore(lock, flags);

	return val;
}
EXPORT_SYMBOL(generic_atomic64_fetch_add_unless);

/* 학습 해설
 * Atomic long 조건 감소·반환 표현식과 실패 유지
 * 고정 커널 atomic_long wrapper와 atomic_t 공식 원문 문서를 대조해 자료형 선택, 연산·순서·진행성의 사용 조건을 배웁니다.
 * dec_if_positive는 정상적인 비음수 입력에서 양수이면 하나 감소하고 그렇지 않으면 유지합니다. 반환은 성공 bool이 아니라 이전 값에서 1을 뺀 계산 결과입니다. 초깃값 0에서는 저장 0과 반환 -1을 구분해야 합니다. 문서의 정상 조건 설명과 구체 backend의 wrap 극단 입력 관찰은 입력 도메인을 명시하여 연결해야 하며 수명 counter의 포화 동작으로 읽으면 안 됩니다.
 * 정상 도메인의 0·1·2에서 실제 저장과 반환을 따로 계산하세요. 큰 음수 경계는 해당 backend와 빌드 옵션을 확인한 별도 사례로 다룹니다. API의 성공 조건과 어떤 값이 반환되는지 모두 확인합니다.
 */
raw_atomic_long_dec_if_positive(atomic_long_t *v)
{
#ifdef CONFIG_64BIT
	return raw_atomic64_dec_if_positive(v);
#else
	return raw_atomic_dec_if_positive(v);
#endif
}

#endif /* _LINUX_ATOMIC_LONG_H */
