/* 학습 해설
 * Atomic API 명세 table·문자 메타데이터의 분류
 * 고정 Linux의 원자 API 명세와 쉘 코드 생성기를 읽어 메타데이터·템플릿·타입 연결로 일관된 C API를 만드는 기술을 배웁니다.
 * atomics.tbl은 함수 이름, 생성할 변형을 나타내는 meta 문자와 인자 목록을 가진 원천 명세입니다. v는 void, b·B는 bool, i·I는 기본 정수, R은 _return, f·F는 fetch, l·s는 load·store를 표현합니다. 대문자 여부는 특정 acquire·release·relaxed 변형 생성과 연결됩니다. meta_in은 shell case의 문자 집합 패턴으로 한 meta가 지정 분류에 속하는지 판정합니다. 성공은 shell 상태 0이며 C bool의 1과 다릅니다.
 * table 한 행을 이름·meta 문자열·타입과 이름으로 나누어 읽습니다. add의 vRF를 세 API 계열로 펼쳐보고 조건 함수의 fb와 비교하세요. shell의 종료 상태 0과 원자 API가 반환하는 bool 또는 정수 값을 혼동하지 않습니다.
 */
#meta_in(meta, match)
meta_in()
{
	case "$1" in
	[$2]) return 0;;
	esac

	return 1
}

#meta_has_ret(meta)
meta_has_ret()
{
	meta_in "$1" "bBiIfFlR"
}

#meta_has_acquire(meta)
meta_has_acquire()
{
	meta_in "$1" "BFIlR"
}

#meta_has_release(meta)
meta_has_release()
{
	meta_in "$1" "BFIRs"

/* 학습 해설
 * Atomic generator 반환 타입·meta와 기본 정수 폭
 * 고정 Linux의 원자 API 명세와 쉘 코드 생성기를 읽어 메타데이터·템플릿·타입 연결로 일관된 C API를 만드는 기술을 배웁니다.
 * gen_ret_type은 s·v를 void, b·B를 bool, 정수 반환 분류를 호출자가 지정한 int·s64·long 문자열로 바꿉니다. meta_has_ret는 실제 return 문장이 필요한 분류를 검사합니다. 하나의 기본 정수 이름을 매개변수로 받아 atomic·atomic64·atomic_long의 다른 타입에 같은 생성 규칙을 적용하는 방식입니다. 반환 타입과 반환 값의 의미는 table과 해당 템플릿을 함께 읽어야 합니다.
 * 선택한 meta와 기본 정수 문자열을 대입하여 출력 선언을 직접 만들어 보세요. bool 반환과 old·updated value 반환을 구별합니다. 생성기가 타입 문자열을 출력한다는 점과 실제 C 계산의 실행을 분리합니다.
 */
#gen_ret_type(meta, int)
gen_ret_type() {
	local meta="$1"; shift
	local int="$1"; shift

	case "${meta}" in
	[sv]) printf "void";;
	[bB]) printf "bool";;
	[aiIfFlR]) printf "${int}";;
	esac
}

#gen_ret_stmt(meta)
gen_ret_stmt()
{
	if meta_has_ret "${meta}"; then
		printf "return ";
	fi
}

# gen_param_name(arg)
gen_param_name()
{
	# strip off the leading 'c' for 'cv'
	local name="${1#c}"
	printf "${name#*:}"

/* 학습 해설
 * Atomic generator 인자 이름·콜론과 const prefix 제거
 * 고정 Linux의 원자 API 명세와 쉘 코드 생성기를 읽어 메타데이터·템플릿·타입 연결로 일관된 C API를 만드는 기술을 배웁니다.
 * gen_param_name은 cv의 앞 c를 제거한 뒤 콜론 뒤 이름을 선택합니다. cv의 기본 이름은 v이며 i:new는 new, p:old는 old가 됩니다. gen_param은 별도 계산한 타입 문자열과 이름을 붙여 선언을 만듭니다. shell의 #·%% 같은 parameter expansion은 prefix·suffix 문자열 제거이며 C 포인터 역참조나 비트 연산이 아닙니다.
 * 타입 선택과 이름 선택을 서로 다른 단계로 적으세요. i:old와 p:old는 이름은 같지만 생성한 타입이 다릅니다. shell expansion과 C 연산을 언어별로 구별하면서 원문을 읽습니다.
 */
# gen_param_name(arg)
gen_param_name()
{
	# strip off the leading 'c' for 'cv'
	local name="${1#c}"
	printf "${name#*:}"
}

# gen_param_type(arg, int, atomic)
gen_param_type()
{
	local type="${1%%:*}"; shift
	local int="$1"; shift
	local atomic="$1"; shift

	case "${type}" in
	i) type="${int} ";;
	p) type="${int} *";;
	v) type="${atomic}_t *";;
	cv) type="const ${atomic}_t *";;
	esac

	printf "${type}"
}

#gen_param(arg, int, atomic)

/* 학습 해설
 * Atomic generator 동적 변수 문맥·주석 인자와 실제 참조
 * 고정 Linux의 원자 API 명세와 쉘 코드 생성기를 읽어 메타데이터·템플릿·타입 연결로 일관된 C API를 만드는 기술을 배웁니다.
 * gen_ret_stmt의 주석은 meta 인자를 적지만 본문은 $1을 local meta에 대입하지 않고 변수 meta를 참조합니다. 정상 생성 호출은 호출자의 local meta 문맥 안에서 실행되어 원하는 return 문장을 만듭니다. 검사에서 meta=B를 설정한 뒤 gen_ret_stmt v를 직접 호출하면 인자 v와 달리 return 문장이 나왔습니다. 작은 helper라도 함수 주석만으로 독립적인 순수 함수라고 추측하면 실제 shell 변수 의존성을 놓칩니다.
 * 함수의 실제 변수 대입과 읽기를 표시하고 호출 문맥을 확인하세요. 인자와 동적 변수 이름이 같은 경우를 독립적인 외부 호출로 재사용할 때 특히 검토합니다. 이 관찰을 고정 generator의 정상 출력 실패라고 해석하지 않습니다.
